WITH selected AS (
  SELECT geometry FROM countries WHERE name IN ('Niger', 'Laos', 'Georgia')
),
hull AS (
  SELECT ST_ConvexHull(ST_Union_Agg(geometry)) AS geom FROM selected
)
SELECT ST_Area_Spheroid(geom)/1e6 AS area_sq_km,
       ST_Area_Spheroid(geom)/1e6 > 5000000 AS exceeds_threshold
FROM hull;

WITH niger AS (
  SELECT ST_Transform(geometry, 'EPSG:4326', 'EPSG:32632', always_xy := true) AS geom
  FROM countries WHERE name = 'Niger'
),
centroid AS (
  SELECT ST_Centroid(geom) AS cent, geom FROM niger
),
diff AS (
  SELECT ST_Difference(geom, ST_Buffer(cent, 100000)) AS geom FROM centroid
)
SELECT ST_Area(geom)/1e6 AS area_sq_km FROM diff;

WITH georgia AS (
  SELECT ST_Transform(geometry, 'EPSG:4326', 'EPSG:32638', always_xy := true) AS geom
  FROM countries WHERE name = 'Georgia'
),
buffered AS (
  SELECT ST_Buffer(geom, 50000) AS geom FROM georgia
),
centroid AS (
  SELECT ST_Centroid(geom) AS geom FROM buffered
),
centroid_4326 AS (
  SELECT ST_Transform(geom, 'EPSG:32638', 'EPSG:4326', always_xy := true) AS geom FROM centroid
)
SELECT ST_X(geom) AS lon, ST_Y(geom) AS lat FROM centroid_4326;

WITH selected AS (
  SELECT geometry FROM lakes WHERE feature_class = 'Lake' AND scalerank = 0
),
hull AS (
  SELECT ST_ConvexHull(ST_Union_Agg(geometry)) AS geom FROM selected
)
SELECT ST_Area_Spheroid(geom)/1e6 AS area_sq_km,
       ST_Area_Spheroid(geom)/1e6 > 10000000 AS exceeds_threshold
FROM hull;
